function readHashRoute() {
  const parts = location.hash.replace(/^#\/?/, '').split('/').filter(Boolean);
  if(parts[0]==='documentos'&&parts[1])return{page:'pdf-editor',documentId:decodeURIComponent(parts[1])};
  if(parts[0]==='documentos')return{page:'documents',documentId:null};
  if (parts[0] === 'curriculums') return { page: 'library', activeId: null, section: 'personal' };
  if (parts[0] === 'editar' && parts[1]) return { page: 'editor', activeId: decodeURIComponent(parts[1]), section: ROUTE_SECTIONS.includes(parts[2]) ? parts[2] : 'personal' };
  return { page: 'home', activeId: null, section: 'personal' };
}
