  const [documents,setDocuments]=useState(null),[error,setError]=useState(''),[originalPage,setOriginalPage]=useState(1),[reconstructedPage,setReconstructedPage]=useState(1),[originalZoom,setOriginalZoom]=useState(100),[reconstructedZoom,setReconstructedZoom]=useState(100),[syncZoom,setSyncZoom]=useState(true);
