  const changeZoom=(side,value)=>{const zoom=Number(value);if(side==='original')setOriginalZoom(zoom);else setReconstructedZoom(zoom);if(syncZoom){if(side==='original')setReconstructedZoom(zoom);else setOriginalZoom(zoom)}};
