 if(section==='education')return <><EditorIntro eyebrow="TU FORMACIÓN" title="Aprender también es avanzar." desc="Incluye los estudios más relevantes para tu próximo paso profesional."/><EditableList title="Educación" items={cv.education} onChange={eduChange} makeItem={()=>({id:uid(),institution:'',degree:'',start:'',end:'',status:'',description:''})} icon={GraduationCap} empty="Añade tus estudios, cursos académicos o formación relevante." addLabel="Agregar estudio" renderItem={(x,upd)=><><div className="form-grid"><Field label="Universidad o institución" value={x.institution} onChange={v=>upd({institution:v})} placeholder="Nombre de la institución"/><Field label="Carrera o título" value={x.degree} onChange={v=>upd({degree:v})} placeholder="Ej. Ingeniería en Sistemas"/><Field label="Fecha de inicio" type={cv.sourcePdf?'text':'month'} value={x.start} onChange={v=>upd({start:v})}/><Field label="Fecha de finalización" type={cv.sourcePdf?'text':'month'} value={x.end} onChange={v=>upd({end:v})}/></div><Field label="Estado académico" value={x.status} onChange={v=>upd({status:v})} placeholder="Ej. Graduado, en curso, egresado"/><div className="spacer-12"/><Field label="Descripción adicional" textarea value={x.description} onChange={v=>upd({description:v})} placeholder="Mención honorífica, cursos relevantes…"/></>}/></>;
 if(section==='skills')return <><EditorIntro eyebrow="LO QUE SABES HACER" title="Tus habilidades, en primer plano." desc="Agrega competencias relevantes para el puesto. Pulsa Enter o coma para añadir cada una."/><div className="form-section"><div className="section-heading"><span className="section-icon"><Sparkles size={17}/></span><div><h3>Habilidades</h3><p>Organízalas por tipo para que sean fáciles de encontrar.</p></div></div>{[['technical','Habilidades técnicas','Ej. Análisis de datos, React, gestión de proyectos'],['soft','Habilidades blandas','Ej. Comunicación, liderazgo, pensamiento crítico'],['tools','Herramientas y tecnologías','Ej. Figma, Excel, Jira, AWS']].map(([key,label,hint])=><SkillInput key={key} label={label} hint={hint} value={cv.skills?.[key]||[]} onChange={arr=>update(x=>({...x,skills:{...x.skills,[key]:arr}}))}/>)}</div></>;
